delivery_evidence_provider_truth.value:
"delivery_evidence"."state" not in ('provider-accepted', 'delivered') or (
        "delivery_evidence"."provider" is not null and "delivery_evidence"."provider_reference" is not null
      )

delivery_test_reports_channels_shape.value:
jsonb_typeof("delivery_test_reports"."channels") is not distinct from 'array'
        and (
          jsonb_array_length("delivery_test_reports"."channels") between 2 and 3
          or (
            jsonb_array_length("delivery_test_reports"."channels") = 1
            and jsonb_array_length(jsonb_path_query_array(
              "delivery_test_reports"."channels", '$[*] ? (@.channel == "push" || @.channel == "email" || @.channel == "sms")'
            )) = 1
          )
        )

delivery_test_reports_status_reason_trut.value:
(
        "delivery_test_reports"."status" = 'succeeded' and "delivery_test_reports"."reason_code" is null
      ) or (
        "delivery_test_reports"."status" in ('failed', 'incomplete')
        and "delivery_test_reports"."reason_code" is not null
      )

